int grundy[10][10][10][10]; // memoization for rectangle (r1,c1)-(r2,c2) exclusive

int compute_grundy(int r1, int c1, int r2, int c2) {
    if (r1 >= r2 || c1 >= c2) return 0;
    int &g = grundy[r1][c1][r2][c2];
    if (g != -1) return g;

    unordered_set<int> reachable;

    for (int r = r1; r < r2; ++r) {
        for (int c = c1; c < c2; ++c) {
            if (board[r][c] == 'x') continue; // marked cell cannot be chosen

            // Determine the extent of wall conversion in each direction
            int up = r;
            while (up > r1 && board[up-1][c] != 'x' && board[up-1][c] != '#') up--;
            int down = r+1;
            while (down < r2 && board[down][c] != 'x' && board[down][c] != '#') down++;
            int left = c;
            while (left > c1 && board[r][left-1] != 'x' && board[r][left-1] != '#') left--;
            int right = c+1;
            while (right < c2 && board[r][right] != 'x' && board[r][right] != '#') right++;

            // The move splits the rectangle into up to 4 subrectangles
            int xor_sum = 0;
            // top-left: (r1,c1) to (up, left)
            xor_sum ^= compute_grundy(r1, c1, up, left);
            // top-right: (r1, right) to (up, c2)
            xor_sum ^= compute_grundy(r1, right, up, c2);
            // bottom-left: (down, c1) to (r2, left)
            xor_sum ^= compute_grundy(down, c1, r2, left);
            // bottom-right: (down, right) to (r2, c2)
            xor_sum ^= compute_grundy(down, right, r2, c2);

            reachable.insert(xor_sum);
        }
    }

    // mex
    int mex = 0;
    while (reachable.count(mex)) mex++;
    return g = mex;
}

