#include <bits/stdc++.h>
using namespace std;

/*
Wall Making Game

State:
- Board cells are either:
  '.' empty (playable)
  'X' marked (not playable, but can be turned into wall)
  '#' wall (already blocked)

A move on an empty cell makes a cross:
- chosen cell and contiguous cells in 4 directions
- stops when hitting wall '#' or board edge
- marked 'X' are also converted to wall

Observation:
Walls split the board into independent rectangular subgames.
For any rectangle [r1..r2] x [c1..c2], if we choose (i,j), then
the cross partitions the remaining cells into up to 4 independent rectangles:
top-left, top-right, bottom-left, bottom-right relative to (i,j),
bounded by the row/column of the new cross.

We compute Grundy number for every subrectangle.
Only empty cells '.' are legal moves.

Let G(r1,r2,c1,c2) be Grundy of that rectangle.
For every empty cell (i,j) inside:
  val =
    G(r1, i-1, c1, j-1) xor
    G(r1, i-1, j+1, c2) xor
    G(i+1, r2, c1, j-1) xor
    G(i+1, r2, j+1, c2)
Take mex of all such vals.

Marked cells 'X' simply are not legal moves, but they still belong to rectangles
and can be removed by future crosses. This recurrence remains valid.

Board size is small enough for O(H^2 W^2 * H * W) with memoization.
*/

int H, W;
vector<string> board;

static int dp[21][21][21][21];
static bool vis[21][21][21][21];

int grundy(int r1, int r2, int c1, int c2) {
    if (r1 > r2 || c1 > c2) return 0;
    if (vis[r1][r2][c1][c2]) return dp[r1][r2][c1][c2];
    vis[r1][r2][c1][c2] = true;

    unordered_set<int> seen;

    for (int i = r1; i <= r2; ++i) {
        for (int j = c1; j <= c2; ++j) {
            if (board[i][j] != '.') continue; // only empty cells are playable

            int g = 0;
            g ^= grundy(r1, i - 1, c1, j - 1);
            g ^= grundy(r1, i - 1, j + 1, c2);
            g ^= grundy(i + 1, r2, c1, j - 1);
            g ^= grundy(i + 1, r2, j + 1, c2);

            seen.insert(g);
        }
    }

    int mex = 0;
    while (seen.count(mex)) ++mex;
    dp[r1][r2][c1][c2] = mex;
    return mex;
}

