#include <stdio.h>
#include <string.h>

#define MAXH 50
#define MAXW 50
#define MAXN 55

static int H, W;
static char board[MAXH][MAXW + 1];

/*
Sprague-Grundy on rectangles.

For a sub-rectangle [r1..r2] x [c1..c2], a move is choosing an empty cell '.'
inside it. That move turns its whole row segment and column segment inside the
current rectangle into walls, splitting the rectangle into up to 4 independent
sub-rectangles:
  top-left, top-right, bottom-left, bottom-right

A marked cell '#' cannot be chosen, so it simply blocks moves. We precompute
whether a rectangle contains at least one empty cell, and compute Grundy by
memoization.
*/

static int sg[MAXN][MAXN][MAXN][MAXN];
static unsigned char vis[MAXN][MAXN][MAXN][MAXN];
static int pref[MAXN][MAXN]; // count of empty cells '.'

static int empty_count(int r1, int c1, int r2, int c2) {
    if (r1 > r2 || c1 > c2) return 0;
    return pref[r2 + 1][c2 + 1] - pref[r1][c2 + 1] - pref[r2 + 1][c1] + pref[r1][c1];
}

static int grundy(int r1, int c1, int r2, int c2) {
    if (r1 > r2 || c1 > c2) return 0;
    if (empty_count(r1, c1, r2, c2) == 0) return 0;
    if (vis[r1][c1][r2][c2]) return sg[r1][c1][r2][c2];
    vis[r1][c1][r2][c2] = 1;

    int maxmoves = (r2 - r1 + 1) * (c2 - c1 + 1);
    static unsigned char seen[2600];
    memset(seen, 0, sizeof(seen));

    for (int i = r1; i <= r2; i++) {
        for (int j = c1; j <= c2; j++) {
            if (board[i][j] != '.') continue;

            int g = 0;
            g ^= grundy(r1, c1, i - 1, j - 1);
            g ^= grundy(r1, j + 1, i - 1, c2);
            g ^= grundy(i + 1, c1, r2, j - 1);
            g ^= grundy(i + 1, j + 1, r2, c2);

            if (g <= maxmoves) seen[g] = 1;
        }
    }

    int mex = 0;
    while (seen[mex]) mex++;
    sg[r1][c1][r2][c2] = mex;
    return mex;
}

int main(void) {
    if (scanf("%d %d", &H, &W) != 2) return 0;
