def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    it = iter(input_data)
    H = int(next(it))
    W = int(next(it))
    board = [list(next(it).strip()) for _ in range(H)]

    # Directions: up, down, left, right
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]

    visited = [[False]*W for _ in range(H)]

    def get_region_cells(start_r, start_c):
        """BFS to collect all cells in the same empty region."""
        stack = [(start_r, start_c)]
        visited[start_r][start_c] = True
        cells = []
        while stack:
            r, c = stack.pop()
            cells.append((r, c))
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W:
                    if not visited[nr][nc] and board[nr][nc] != '#':
                        visited[nr][nc] = True
                        stack.append((nr, nc))
        return cells

    def grundy_of_region(cells):
        """Compute Grundy number for a region of empty cells."""
        # Map cell positions to indices
        idx_map = {}
        for idx, (r, c) in enumerate(cells):
            idx_map[(r, c)] = idx
        n = len(cells)

        # Precompute reachable cells from each cell in the plus shape
        reachable = []
        for r, c in cells:
            seen = set()
            seen.add((r,c))
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                while 0 <= nr < H and 0 <= nc < W and board[nr][nc] != '#':
                    seen.add((nr, nc))
                    nr += dr
                    nc += dc
            reachable.append([idx_map[pos] for pos in seen if pos in idx_map])

        # Use DP with bitmask over small regions (n <= 20 typically for Grundy)
        # However, region size can be up to H*W, so we use memoization on sets.
        from functools import lru_cache

        # Represent state as a frozenset of remaining indices
        full_set = frozenset(range(n))

        @lru_cache(None)
        def grundy(state):
            if not state:
                return 0
            moves = set()
            for i in state:
                # removal set
                removed = set()
                for j in reachable[i]:
                    if j in state:
                        removed.add(j)
                new_state = state - removed
                g = grundy(new_state)
                moves.add(g)
            # mex
            g = 0
            while g in moves:
                g += 1
            return g

        return grundy(full_set)

    total_xor = 0
    for r in range(H):
        for c in range(W):
            if board[r][c] != '#' and not visited[r][c]:
                cells = get_region_cells(r, c)
                g = grundy_of_region(cells)
                total_xor ^= g

    if total_xor != 0:
        print("First")
    else:
        print("Second")

if __name__ == "__main__":
    solve()

