def main():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    h, w = map(int, data[0].split())
    board = [list(line.strip()) for line in data[1:1+h]]

    # Prefix sum of cells that are NOT walls initially.
    # Only initial walls split regions. Marked cells are still part of a region.
    pref = [[0]*(w+1) for _ in range(h+1)]
    for i in range(h):
        row_sum = 0
        for j in range(w):
            row_sum += 1 if board[i][j] != '#' else 0
            pref[i+1][j+1] = pref[i][j+1] + row_sum

    def has_nonwall(r1, r2, c1, c2):
        if r1 > r2 or c1 > c2:
            return False
        s = pref[r2+1][c2+1] - pref[r1][c2+1] - pref[r2+1][c1] + pref[r1][c1]
        return s > 0

    from functools import lru_cache

    @lru_cache(None)
    def grundy(r1, r2, c1, c2):
        if r1 > r2 or c1 > c2:
            return 0
        if not has_nonwall(r1, r2, c1, c2):
            return 0

        reachable = []

        for i in range(r1, r2 + 1):
            for j in range(c1, c2 + 1):
                if board[i][j] != '.':
                    continue  # only empty cells can be chosen

                # Choosing (i,j) creates a cross of walls splitting rectangle
                # into up to 4 independent subrectangles.
                g = (
                    grundy(r1, i - 1, c1, j - 1) ^
                    grundy(r1, i - 1, j + 1, c2) ^
                    grundy(i + 1, r2, c1, j - 1) ^
                    grundy(i + 1, r2, j + 1, c2)
                )
                reachable.append(g)

        return mex(reachable)

    g = grundy(0, h - 1, 0, w - 1)
    print("First" if g != 0 else "Second")

