/*
 * Wall Making Game
 *
 * Sprague-Grundy on subrectangles.
 *
 * Let solve(r1,r2,c1,c2) be the Grundy number of the subgame restricted to the
 * rectangle [r1..r2] x [c1..c2], assuming cells outside are already blocked.
 *
 * A move is choosing an empty cell (not marked) inside this rectangle such that
 * the whole cross from that cell to the rectangle borders contains no existing wall.
 * In the recursive decomposition used here, existing walls are exactly the borders
 * of the current subrectangle, while marked cells are just unplayable but do not
 * block propagation.
 *
 * Choosing (i,j) splits the rectangle into four independent rectangles:
 *   top-left     [r1..i-1] x [c1..j-1]
 *   top-right    [r1..i-1] x [j+1..c2]
 *   bottom-left  [i+1..r2] x [c1..j-1]
 *   bottom-right [i+1..r2] x [j+1..c2]
 *
 * Grundy = mex of xor of the four parts over all legal moves.
 *
 * If overall Grundy != 0 => First wins, else Second wins.
 */
public class Main {
    static int H, W;
    static char[][] board;

    static int[][][][] memo;
    static boolean[][][][] vis;

    static int grundy(int r1, int r2, int c1, int c2) {
        if (r1 > r2 || c1 > c2) return 0;
        if (vis[r1][r2][c1][c2]) return memo[r1][r2][c1][c2];
        vis[r1][r2][c1][c2] = true;

        HashSet<Integer> set = new HashSet<>();

        for (int i = r1; i <= r2; i++) {
            for (int j = c1; j <= c2; j++) {
                if (board[i][j] != '.') continue; // only empty cells are playable

                int g = grundy(r1, i - 1, c1, j - 1)
                      ^ grundy(r1, i - 1, j + 1, c2)
                      ^ grundy(i + 1, r2, c1, j - 1)
                      ^ grundy(i + 1, r2, j + 1, c2);
                set.add(g);
            }
        }

        int mex = 0;
        while (set.contains(mex)) mex++;
        memo[r1][r2][c1][c2] = mex;
        return mex;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        H = fs.nextInt();
        W = fs.nextInt();
        board = new char[H][W];
        for (int i = 0; i < H; i++) {
            String s = fs.next();
            board[i] = s.toCharArray();
        }

        memo = new int[H][H][W][W];
        vis = new boolean[H][H][W][W];

        int g = grundy(0, H - 1, 0, W - 1);
        System.out.println(g != 0 ? "First" : "Second");
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

